package bottlesong

import "fmt"

// Recite returns the lyrics for takeDown consecutive verses, starting with
// startBottles bottles on the wall. Verses are separated by a blank line.
func Recite(startBottles, takeDown int) []string {
	var lines []string
	for i := 0; i < takeDown; i++ {
		if i > 0 {
			lines = append(lines, "")
		}
		lines = append(lines, verse(startBottles-i)...)
	}
	return lines
}

// verse returns the four lines of the verse for the given number of bottles.
func verse(n int) []string {
	return []string{
		fmt.Sprintf("%s green %s hanging on the wall,", numberWord(n), bottle(n)),
		fmt.Sprintf("%s green %s hanging on the wall,", numberWord(n), bottle(n)),
		"And if one green bottle should accidentally fall,",
		fmt.Sprintf("There'll be %s green %s hanging on the wall.", numberWord(n-1), bottle(n-1)),
	}
}

// bottle returns the singular or plural form of "bottle".
func bottle(n int) string {
	if n == 1 {
		return "bottle"
	}
	return "bottles"
}

// numberWord returns the English word for n, capitalized, or "no" for zero.
func numberWord(n int) string {
	switch n {
	case 0:
		return "no"
	case 1:
		return "One"
	case 2:
		return "Two"
	case 3:
		return "Three"
	case 4:
		return "Four"
	case 5:
		return "Five"
	case 6:
		return "Six"
	case 7:
		return "Seven"
	case 8:
		return "Eight"
	case 9:
		return "Nine"
	case 10:
		return "Ten"
	default:
		return fmt.Sprintf("%d", n)
	}
}

