package bottlesong

import (
	"fmt"
	"unicode"
)

// Recite returns the lyrics for takeDown consecutive verses, starting with
// startBottles bottles on the wall. Verses are separated by a blank line.
func Recite(startBottles, takeDown int) []string {
	var lines []string
	for i := 0; i < takeDown; i++ {
		if i > 0 {
			lines = append(lines, "")
		}
		lines = append(lines, verse(startBottles-i)...)
	}
	return lines
}

// verse returns the four lines of the verse for the given number of bottles.
func verse(n int) []string {
	lead := capitalize(numberWord(n))
	return []string{
		fmt.Sprintf("%s green %s hanging on the wall,", lead, bottle(n)),
		fmt.Sprintf("%s green %s hanging on the wall,", lead, bottle(n)),
		"And if one green bottle should accidentally fall,",
		fmt.Sprintf("There'll be %s green %s hanging on the wall.", numberWord(n-1), bottle(n-1)),
	}
}

// bottle returns the singular or plural form of "bottle".
func bottle(n int) string {
	if n == 1 {
		return "bottle"
	}
	return "bottles"
}

// numberWord returns the lowercase English word for n, or "no" for zero.
func numberWord(n int) string {
	switch n {
	case 0:
		return "no"
	case 1:
		return "one"
	case 2:
		return "two"
	case 3:
		return "three"
	case 4:
		return "four"
	case 5:
		return "five"
	case 6:
		return "six"
	case 7:
		return "seven"
	case 8:
		return "eight"
	case 9:
		return "nine"
	case 10:
		return "ten"
	default:
		return fmt.Sprintf("%d", n)
	}
}

// capitalize uppercases the first rune of s and leaves the rest unchanged.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	r := []rune(s)
	r[0] = unicode.ToUpper(r[0])
	return string(r)
}

